+import { $internal } from '../../common';
+import type { Entity } from '../../entity/types';
+import { getEntityId } from '../../entity/utils/pack-entity';
+import type { RelationPair } from '../../relation/types';
+import type { Trait } from '../../trait/types';
+import type { World } from '../../world';
+import type { EventType, QueryInstance, TrackingGroup } from '../types';
+import { checkQueryTracking } from './check-query-tracking';
+
+function pairKey(pair: RelationPair, target: Entity): string {
+    const { relation, target: expected } = pair[$internal];
+    return `${relation[$internal].trait.id}:${expected === '*' ? target : expected}`;
+}
+
+function matchesPair(pair: RelationPair, trait: Trait, target: Entity): boolean {
+    const context = pair[$internal];
+    return context.relation[$internal].trait === trait && (context.target === '*' || context.target === target);
+}
+
+function pairGroupMatches(group: TrackingGroup, entity: Entity): boolean {
+    const tracked = group.pairTrackers?.get(entity);
+    if (!tracked?.size) return false;
+
+    const pairs = group.relationPairs!;
+    if (group.logic === 'or') return pairs.some((pair) => [...tracked].some((key) => key.startsWith(`${pair[$internal].relation[$internal].trait.id}:`)));
+    return pairs.every((pair) =>
+        [...tracked].some((key) => key.startsWith(`${pair[$internal].relation[$internal].trait.id}:`) && (pair[$internal].target === '*' || key === pairKey(pair, pair[$internal].target as Entity)))
+    );
+}
+
+/** Record a relation-target event for pair-aware tracking modifiers. */
+export function setPairTrackingEvent(
+    world: World,
+    entity: Entity,
+    trait: Trait,
+    target: Entity,
+    eventType: EventType
+): void {
+    const instance = world[$internal].traitInstances[trait.id];
+    if (!instance) return;
+
+    for (const query of instance.trackingQueries) {
+        const pairGroups = query.trackingGroups.filter((group) => group.relationPairs?.some((pair) => matchesPair(pair, trait, target)));
+        if (!pairGroups.length) continue;
+
+        for (const group of pairGroups) {
+            const matchingPairs = group.relationPairs!.filter((pair) => matchesPair(pair, trait, target));
+            const trackers = group.pairTrackers!;
+            let tracked = trackers.get(entity);
+            if (!tracked) trackers.set(entity, (tracked = new Set()));
+
+            for (const pair of matchingPairs) {
+                const key = pairKey(pair, target);
+                if (group.type === eventType) tracked.add(key);
+                // Opposite structural events on the same target cancel in this observation window.
+                else if ((eventType === 'add' || eventType === 'remove') && (group.type === 'add' || group.type === 'remove')) tracked.delete(key);
+            }
+            if (!tracked.size) trackers.delete(entity);
+        }
+
+        const genericMatch = checkQueryTracking(world, query, entity, eventType, instance.generationId, 0);
+        const pairsMatch = query.trackingGroups
+            .filter((group) => group.relationPairs?.length)
+            .every((group) => pairGroupMatches(group, entity));
+
+        if (genericMatch && pairsMatch) {
+            query.pairTargets.set(entity, target);
+            query.add(entity);
+        } else {
+            query.remove(world, entity);
+            if (!query.entities.has(entity)) query.pairTargets.delete(entity);
+        }
+    }
+}
+
+export function resetPairTracking(query: QueryInstance, entity: Entity): void {
+    for (const group of query.trackingGroups) group.pairTrackers?.delete(entity);
+    query.pairTargets.delete(entity);
+}
